entries[178019] = { ["name"] = "Ereignis: Aufgeladenes Erz", ["text"] = "Unbegrenzte Reichweite\nSofort\nSammelt aufgeladenes Erz am Geschmolzenen Steinbruch und bringt es zum Minenwagen Eurer Fraktion. Die Fraktion, die als erste 20 Erz sammelt, gewinnt.\n\nBelohnung\nWenn Ihr dieses Ereignis gewinnt, erhaltet Ihr:\n\nVerbeulte Schließkassette der Aschehämmer" }
entries[178020] = { ["name"] = "Ereignis: Auferstandene Geister", ["text"] = "Unbegrenzte Reichweite\nSofort\nFangt 20 der auferstandenen Geister ein, die auf dem Friedhof der Aschehämmer spuken. Die Fraktion, die als erste 20 von ihnen fängt, gewinnt.\n\nBelohnung\nWenn Ihr dieses Ereignis gewinnt, erhaltet Ihr:\n\nVerbeulte Schließkassette der Aschehämmer" }
entries[178021] = { ["name"] = "Ereignis: Ogerfeuer", ["text"] = "Unbegrenzte Reichweite\nSofort\nEntzündet die Feuergruben der Oger am Schlägerplateau. Fraktionen, die die Feuer einnehmen, erhalten Punkte. Wer zuerst 1500 Punkte erreicht, gewinnt.\n\nBelohnungen\nWenn Ihr dieses Ereignis gewinnt, erhaltet Ihr:\n\nVerbeulte Schließkassette der Aschehämmer" }
entries[178022] = { ["name"] = "Ereignis: Stadionrennen", ["text"] = "Unbegrenzte Reichweite\nSofort\nIm Amphitheater der Auslöschung findet ein Rennen zwischen Horde und Allianz statt. Die Fraktion, die als erste 5 Runden abschließt, gewinnt.\n\nBelohnung\nWenn Ihr dieses Ereignis gewinnt, erhaltet Ihr:\n\nVerbeulte Schließkassette der Aschehämmer" }
