entries[178236] = { ["name"] = "Tod von oben", ["text"] = "15 Meter Reichweite\nSofort\nBenötigt Einhändige Nahkampfwaffe\nFinishing-Move, der Eure Waffen mit Schattenenergie verstärkt und einen vernichtenden zweiteiligen Angriff ausführt.\n\nIhr wirbelt herum, fügt allen Gegnern innerhalb von 8 Metern (57.33% der Angriffskraft) Schaden zu, springt dann in die Luft und setzt auf dem Weg nach unten [ Vergiften : 'Vergiften' ] [ Tötung : 'Tötung' / 'Ausweiden' ] mit solcher Wucht gegen Euer Ziel ein, dass der Effekt der Fähigkeit um 50% erhöht wird." }
