entries[178534] = { ["name"] = "Hexenmeisterportale", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Hexenmeister des Vorpostens des Kriegsspeers haben die Portale in Ashran aktiviert.\n\nAuf Eurer Karte findet Ihr sie im Nordwesten und Südosten Ashrans. Benutzt sie, um schneller durch Ashran zu reisen.\n\nWenn 400 [Artefaktfragmente] , die in ganz Ashran gefunden werden können, bei Nisstyr im Vorposten des Kriegsspeers abgegeben wurden, werden die Portale aktiviert." }
entries[178535] = { ["name"] = "Hexenmeisterportale", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Hexenmeister der Sturmschildfeste haben die Portale in Ashran aktiviert.\n\nAuf Eurer Karte findet Ihr sie im Nordwesten und Südosten Ashrans. Benutzt sie, um schneller durch Ashran zu reisen.\n\nWenn 400 [Artefaktfragmente] , die in ganz Ashran gefunden werden können, bei Marketa im Vorposten des Kriegsspeers abgegeben wurden, werden die Portale aktiviert." }
entries[178536] = { ["name"] = "Wolfsreiter", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Wolfsreiter des Vorpostens des Kriegsspeers sind ausgesandt worden, um in den Außenbereichen von Ashran alle Allianzmitglieder aufzuspüren, die sich dort aufhalten.\n\nZum Ausrüsten der Wolfsreiter werden [Artefaktfragmente] benötigt, die in ganz Ashran zu finden sind. Gebt sie bei Kalgan im Vorposten des Kriegsspeers ab." }
entries[178537] = { ["name"] = "Kavallerie der Vergeltung", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Sturmschildkavallerie ist ausgesandt worden, um in den Außenbereichen von Ashran alle Mitglieder der Horde aufzuspüren, die sich dort aufhalten.\n\nZum Ausrüsten der Kavallerie werden [Artefaktfragmente] benötigt, die in ganz Ashran zu finden sind. Gebt sie bei Valant Lichtschwur in der Sturmschildfeste ab." }
entries[178538] = { ["name"] = "Magierportal", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Magier der Sturmschildfeste haben das Magierportal in Ashran aktiviert. Benutzt das Portal, um schnell zur Sturmschildfeste zurückzukehren.\n\nAuf Eurer Karte findet Ihr das Magierportal westlich der Ruhestätte der Könige.\n\nWenn 400 [Artefaktfragmente] , die in ganz Ashran gefunden werden können, bei Ecilam in der Sturmschildfeste abgegeben wurden, wird das Portal aktiviert." }
entries[178539] = { ["name"] = "Magierportal", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Magier des Vorpostens des Kriegsspeers haben das Magierportal in Ashran aktiviert. Benutzt das Portal, um schnell zum Vorposten des Kriegsspeers zurückzukehren.\n\nAuf Eurer Karte findet Ihr das Magierportal westlich der Ruhestätte der Könige.\n\nWenn 400 [Artefaktfragmente] , die in ganz Ashran gefunden werden können, bei Fura im Vorposten des Kriegsspeers abgegeben wurden, wird das Portal aktiviert." }
