entries[178543] = { ["name"] = "Starren des Abgrunds", ["text"] = "Sofort\nFügt dem am nächsten stehenden Spielercharakter 29 Schattenschaden zu. Zusätzlich erhöht dieser Effekt den erlittenen Schaden von 'Starren des Abgrunds' 15 Sek. lang um 40%.\n\nWenn 'Starren des Abgrunds' abläuft, fügt der Effekt dem betroffenen Ziel und seinen Verbündeten innerhalb von 8 Metern 117 Schattenschaden zu." }
